{
    let stdout = 1;
    let message = b"Hello, world!\n";
    let mut sent = 0;
    while sent < message.len() {
        let remaining = &message[sent..];
        let written = write(stdout, remaining, remaining.len());
        if written == -EINTR { continue; }
        if written <= 0 { return 1; }
        sent += written as Usize;
    }
    return 0;
}
